import{_ as o,o as r,c as t,a5 as e}from"./chunks/framework.Cooo9kuv.js";const b=JSON.parse('{"title":"后台实用工具 — Z-BlogPHP 后台增强插件","description":"","frontmatter":{"标题":"ZBlogPHP 后台增强插件 – 后台实用工具","日期":"2026-07-11T00:00:00.000Z","修改日期":"2026-07-13T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["zblog主题插件"],"标签":["404跳转","Z-BlogPHP","后台增强","安全防护","快捷菜单","管理优化","粘滞布局","蜘蛛拦截"]},"headers":[],"relativePath":"md/zblog主题插件/ZBlogPHP 后台增强插件 - 后台实用工具.md","filePath":"md/zblog主题插件/ZBlogPHP 后台增强插件 - 后台实用工具.md"}'),n={name:"md/zblog主题插件/ZBlogPHP 后台增强插件 - 后台实用工具.md"};function l(s,a,i,h,p,d){return r(),t("div",null,[...a[0]||(a[0]=[e('<h1 id="后台实用工具-—-z-blogphp-后台增强插件" tabindex="-1">后台实用工具 — Z-BlogPHP 后台增强插件 <a class="header-anchor" href="#后台实用工具-—-z-blogphp-后台增强插件" aria-label="Permalink to &quot;后台实用工具 — Z-BlogPHP 后台增强插件&quot;">​</a></h1><blockquote><p>整合多项 Z-BlogPHP 后台增强功能，包括粘滞布局、二级快捷菜单、404 自定义跳转、蜘蛛后台验证拦截、错误6跳转首页、清缓重编按钮、圆形头像、仪表盘精简等，一站式提升后台使用体验与安全防护能力。</p></blockquote><p><strong>版本</strong>：v1.0.0<br><strong>适配</strong>：Z-BlogPHP 1.7.0+<br><strong>PHP</strong>：≥ 7.2<br><strong>作者</strong>：softbangong<br><strong>授权</strong>：不限制网站数量，下载安装后永久免费使用</p><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-5.png" alt=""></p><p>本插件整合了多项 Z-BlogPHP 后台管理界面的增强功能，覆盖界面布局优化、快捷导航、错误页面处理、安全防护、仪表盘精简等多个维度。所有功能均可在后台统一配置，无需手动修改代码即可开启或关闭。</p><p>插件通过 Z-BlogPHP 标准的 Filter 钩子机制注入功能，不修改系统核心文件，启用/禁用均干净无残留。</p><h2 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h2><h3 id="后台粘滞布局-stickylayout" tabindex="-1">后台粘滞布局（StickyLayout） <a class="header-anchor" href="#后台粘滞布局-stickylayout" aria-label="Permalink to &quot;后台粘滞布局（StickyLayout）&quot;">​</a></h3><p>启用后，后台顶部导航栏和左侧侧边栏将固定显示，不随页面滚动，方便在长页面中随时访问导航菜单和快捷入口。</p><p>粘滞布局模块包含两个子选项：</p><p>— <strong>圆形头像</strong>：将后台右上角用户头像显示为圆形样式，视觉更精致<br> — <strong>清缓重编按钮</strong>：在后台顶部导航栏添加「清缓重编」快捷按钮，一键执行缓存清理和内容重编译操作</p><h3 id="二级快捷菜单-mq-menu" tabindex="-1">二级快捷菜单（MQ_Menu） <a class="header-anchor" href="#二级快捷菜单-mq-menu" aria-label="Permalink to &quot;二级快捷菜单（MQ_Menu）&quot;">​</a></h3><p>在后台顶部导航栏添加自定义快捷菜单，支持两级操作：</p><p>— <strong>快捷菜单项</strong>：通过 <code>标题|网址</code> 格式自定义菜单项，每行一项，在顶部导航显示为下拉菜单，鼠标悬停展开，同时兼容移动端触摸操作<br> — <strong>隐藏菜单项</strong>：通过 <code>|</code> 分隔符指定要隐藏的顶部菜单名称，实现导航栏精简</p><h3 id="_404-自定义页面跳转" tabindex="-1">404 自定义页面跳转 <a class="header-anchor" href="#_404-自定义页面跳转" aria-label="Permalink to &quot;404 自定义页面跳转&quot;">​</a></h3><p>当访客访问不存在的页面时，可配置自动跳转到指定的目标 URL，而非显示默认的 404 错误页面：</p><p>— <strong>重定向链接</strong>：支持输入完整的 http/https 地址作为 404 页面跳转目标<br> — <strong>跳转延迟</strong>：可设置 0 到 30 秒的跳转前等待时间，0 秒为立即跳转</p><h3 id="无权限错误跳转首页" tabindex="-1">无权限错误跳转首页 <a class="header-anchor" href="#无权限错误跳转首页" aria-label="Permalink to &quot;无权限错误跳转首页&quot;">​</a></h3><p>启用后，当访客触发错误6（权限不足，如直接访问后台管理页面）时，自动重定向到网站首页，避免暴露默认的错误提示页面结构。</p><h3 id="蜘蛛后台验证拦截" tabindex="-1">蜘蛛后台验证拦截 <a class="header-anchor" href="#蜘蛛后台验证拦截" aria-label="Permalink to &quot;蜘蛛后台验证拦截&quot;">​</a></h3><p>拦截所有主流搜索引擎蜘蛛对 Z-BlogPHP 后台验证接口 <code>/zb_system/cmd.php?act=verify</code> 的访问，将其重定向到登录页面。</p><p>已覆盖搜索引擎蜘蛛：GoogleBot、BaiduSpider、BingBot、360Spider、Sogou Spider、YoudaoBot、ByteSpider、YiSouSpider、iAskSpider 等。</p><p>此功能可有效防止攻击者伪造蜘蛛 User-Agent 进行撞库或暴力破解攻击，同时不影响正常 SEO 收录。</p><h3 id="后台首页精简" tabindex="-1">后台首页精简 <a class="header-anchor" href="#后台首页精简" aria-label="Permalink to &quot;后台首页精简&quot;">​</a></h3><p>启用后自动隐藏后台仪表盘首页中的以下模块：</p><p>— 最新动态信息区域<br> — Z-BlogPHP 网站和程序开发区域</p><p>保持仪表盘界面简洁，减少无关信息干扰。</p><h3 id="通用设置" tabindex="-1">通用设置 <a class="header-anchor" href="#通用设置" aria-label="Permalink to &quot;通用设置&quot;">​</a></h3><p>— <strong>添加到顶部菜单</strong>：控制是否在后台顶部导航栏显示本插件的管理入口，关闭后仍可通过「插件管理」页面访问<br> — <strong>卸载时清空数据</strong>：开启后，卸载插件会同时删除所有配置数据，实现干净卸载</p><h2 id="使用说明" tabindex="-1">使用说明 <a class="header-anchor" href="#使用说明" aria-label="Permalink to &quot;使用说明&quot;">​</a></h2><h3 id="第一步-安装插件" tabindex="-1">第一步：安装插件 <a class="header-anchor" href="#第一步-安装插件" aria-label="Permalink to &quot;第一步：安装插件&quot;">​</a></h3><p>将 <code>admin_tools</code> 文件夹上传至网站 <code>zb_users/plugin/</code> 目录，进入 Z-BlogPHP 后台「插件管理」页面，找到「后台实用工具」并点击启用。</p><h3 id="第二步-配置功能" tabindex="-1">第二步：配置功能 <a class="header-anchor" href="#第二步-配置功能" aria-label="Permalink to &quot;第二步：配置功能&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/07/image-6.png" alt=""></p><p>进入后台「插件管理」或顶部导航栏中「后台实用工具」的设置页面：</p><p>— 每个功能模块独立显示为一张卡片，标题栏右侧设有滑动开关，点击即可即时启用或关闭<br> — 404 跳转和快捷菜单等模块包含子配置项，开关开启后展开对应的配置区域<br> — 配置完成后点击页面底部的「保存设置」按钮即可生效</p><h3 id="第三步-验证效果" tabindex="-1">第三步：验证效果 <a class="header-anchor" href="#第三步-验证效果" aria-label="Permalink to &quot;第三步：验证效果&quot;">​</a></h3><p>— 粘滞布局：滚动后台管理页面，确认导航栏和侧边栏是否固定显示<br> — 快捷菜单：刷新页面后，检查顶部导航栏是否出现自定义快捷菜单下拉项<br> — 404 跳转：访问网站任意不存在的页面，测试是否跳转到配置的目标地址<br> — 蜘蛛拦截：使用浏览器开发者工具修改 User-Agent 为百度蜘蛛，访问验证接口确认是否被拦截</p><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><p>— 粘滞布局与部分主题可能冲突，如出现布局异常请关闭该功能<br> — 404 跳转目标 URL 需填写完整的 http/https 地址，否则跳转不会生效<br> — 蜘蛛拦截仅在访问 <code>/zb_system/cmd.php?act=verify</code> 且 User-Agent 匹配蜘蛛特征时触发，正常访客和搜索引擎抓取不受影响<br> — 隐藏菜单项基于菜单名称匹配，修改后的菜单名称需同步更新配置<br> — 清缓重编按钮依赖 Z-BlogPHP 系统 <code>cmd.php?act=misc&amp;type=statistic</code> 接口，请确保该功能可用</p><h2 id="反馈与支持" tabindex="-1">反馈与支持 <a class="header-anchor" href="#反馈与支持" aria-label="Permalink to &quot;反馈与支持&quot;">​</a></h2><p>— 作者：softbangong<br> — 作者网站：softbangong.com<br> — 邮箱：<a href="mailto:yunjuliangpin@163.com" target="_blank" rel="noreferrer">yunjuliangpin@163.com</a></p><h2 id="更新日志" tabindex="-1">更新日志 <a class="header-anchor" href="#更新日志" aria-label="Permalink to &quot;更新日志&quot;">​</a></h2><h3 id="v1-0-0-2026-07-05" tabindex="-1">v1.0.0（2026-07-05） <a class="header-anchor" href="#v1-0-0-2026-07-05" aria-label="Permalink to &quot;v1.0.0（2026-07-05）&quot;">​</a></h3><p>— 首次发布<br> — 实现粘滞布局、圆形头像、清缓重编按钮三大后台界面增强<br> — 实现二级快捷菜单，支持自定义快捷导航和隐藏顶部菜单<br> — 实现 404 自定义页面跳转，支持延迟跳转<br> — 实现错误6无权限自动跳转首页<br> — 实现蜘蛛后台验证接口拦截，覆盖 9 种主流搜索引擎蜘蛛<br> — 实现仪表盘首页模块精简<br> — 配置文件 JSON 化存储，支持卸载时清空数据选项</p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2970.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2970.html</a></p>',48)])])}const g=o(n,[["render",l]]);export{b as __pageData,g as default};
